  'site.contact.submit': 'கோரிக்கையை அனுப்பவும்',
  'site.contact.agree': 'சமர்ப்பிப்பதன் மூலம் OctaBuild குழு உங்களைத் தொடர்பு கொள்ள ஒப்புக்கொள்கிறீர்கள். உங்கள் விவரங்களை நாங்கள் ஒருபோதும் பகிர மாட்டோம்.',
