  'site.services.card.pmBlurb': 'ചെലവഴിക്കുന്ന ഓരോ രൂപയ്ക്കും വെണ്ടർ മാനേജ്‌മെന്റ്, ഗുണനിലവാര പരിശോധന, നാഴികക്കല്ല് ട്രാക്കിംഗ്.',
