  'site.projects.eyebrow': 'ഞങ്ങളുടെ പ്രവർത്തനം',
  'site.projects.title': 'സ്വയം സംസാരിക്കുന്ന',
  'site.projects.highlight': 'പ്രോജക്ടുകൾ.',
  'site.projects.sub': 'വീടുകൾ, ജോലിസ്ഥലങ്ങൾ, പൊതു അടിസ്ഥാന സൗകര്യങ്ങൾ എന്നിവ ഉൾക്കൊള്ളുന്ന പോർട്ട്ഫോളിയോ — ഓരോന്നും സമയത്തും ബജറ്റിലും നിലവാരത്തിലും വിതരണം ചെയ്തു.',
