  'site.team.role4': 'പ്രോജക്ട്സ് ഡയറക്ടർ',
  'site.team.bio1': 'റോഡുകൾ, തുറമുഖങ്ങൾ, ഉയർന്ന നിലയിലുള്ള റെസിഡൻഷ്യൽ എന്നിവയിൽ 26 വർഷത്തെ സിവിൽ എഞ്ചിനീയർ.',
  'site.team.bio2': 'സുസ്ഥിര ഭവനത്തിലെ അവാർഡ് നേടിയ പ്രവൃത്തിയോടെ ഡിസൈൻ സ്റ്റുഡിയോയെ നയിക്കുന്നു.',
  'site.team.bio3': 'ഭൂകമ്പ മേഖലകൾക്കും കനത്ത ഇൻഫ്രാസ്ട്രക്ചറിനുമുള്ള സ്ട്രക്ചറൽ സ്പെഷ്യലിസ്റ്റ്.',
  'site.team.bio4': 'ഡെലിവറി പ്രവർത്തനങ്ങൾ നടത്തുന്നു — സമയബന്ധിതമായി 850+ പ്രോജക്ടുകൾ.',
