  'site.testi.q2': 'انضباطهم في إدارة المشاريع لا مثيل له. مراحل تحققت، جودة دُققت، وكل روبية محسوبة.',
  'site.testi.r2': 'مدير · سكايلاين إنفرا',
  'site.testi.q3': 'من التراخيص إلى الدهان، تولوا كل شيء. كباني لأول مرة شعرت بالتوجيه في كل خطوة.',
  'site.testi.r3': 'صاحب منزل · سيدار كريك',
  'site.faq.eyebrow': 'الأسئلة الشائعة',
  'site.faq.title': 'أسئلة؟',
  'site.faq.highlight': 'إجابات واضحة.',
  'site.faq.sub': 'كل ما يسأله أصحاب المنازل والشركات عادة قبل بدء البناء. لم تجد سؤالك؟ اكتب لنا في أي وقت.',
  'site.faq.q1': 'كيف يُحدَّد تسعيركم؟',
  'site.faq.a1': 'يبدأ كل مشروع بتقدير موازنة تفصيلي شفاف. توافق على التكاليف قبل أن نبدأ، وخطط الدفع حسب المراحل تعني أنك تدفع فقط عند التحقق من العمل.',
  'site.faq.q2': 'هل تتولون التراخيص والموافقات؟',
  'site.faq.a2': 'نعم. يدير فريق التنسيق لدينا المخططات المعتمدة وإيداعات ريرا وموافقات البلدية من البداية للنهاية، مع إبقائك على اطلاع في كل مرحلة.',
  'site.faq.q3': 'ما المدة النموذجية للمشروع؟',
  'site.faq.a3': 'يستغرق المنزل المستقل القياسي من 8 إلى 14 شهراً حسب الحجم والتصميم. الهياكل التجارية من 9 إلى 18 شهراً. تحصل على جدول مراحل ملزم قبل البدء.',
  'site.faq.q4': 'هل يمكنني متابعة مشروعي عن بُعد؟',
  'site.faq.a4': 'بالتأكيد. يحصل كل عميل على لوحة تحكم مباشرة للمشروع مع تقارير تقدم أسبوعية وتحديثات بالصور واستخدام المواد وتتبع التكاليف.',
  'site.faq.q5': 'ما الضمانات التي تقدمونها؟',
  'site.faq.a5': 'الأعمال الهيكلية مشمولة بضمان 10 سنوات وأنظمة MEP بضمان سنتين، بالإضافة إلى التزام 12 شهراً بخدمة ما بعد البناء لجميع التشطيبات.',
  'site.faq.q6': 'هل تعملون على مشاريع خارج مدنكم؟',
  'site.faq.a6': 'نعمل حالياً في حيدر أباد وبنغالور وتشيناي وبوني ومومباي. للمشاريع التجارية والبنية التحتية الأكبر نتحرك على مستوى الدولة.',
  'site.cta.badge': 'استشارة مجانية',
  'site.cta.title': 'مستعد لوضع حجر الأساس لمشروعك القادم؟',
  'site.cta.sub': 'احصل على زيارة موقع مجانية وتقدير شفاف وجدول زمني ملزم — خلال 48 ساعة من استفسارك.',

