  'site.about.hero.highlight': 'ثقة تبنى بالخرسانة.',
  'site.about.hero.sub': 'من فريق موقع من خمسة أفراد في 2001 إلى واحدة من أكثر شركات البناء الموثوقة في الهند — قصتنا مكتوبة في المباني التي تركناها خلفنا.',
