  'site.about.story.p1': 'بدأت OctaBuild في 2001 ببناء سكني واحد في حيدر أباد ووعد بسيط — أظهر للعميل كل روبية، كل أسبوع. أصبح ذلك الوعد نظام التشغيل لدينا.',
  'site.about.story.p2': 'اليوم نوظف أكثر من 120 مهندساً ومعمارياً ومدير مشروع قدموا أكثر من 850 مشروعاً في المجال السكني والتجاري والبنية التحتية. نستثمر بكثافة في التصميم الداخلي وضمان الجودة لأننا نؤمن بأن الجودة لا يمكن الاستعانة بمصادر خارجية فيها.',
